pub fn fact(n: i64) -> i64 {
    return match n {
        0 => 1,
        _ => n * fact(n - 1),
    };
}

pub fn pick(s: &str, n: i64) -> String {
    let first = format!("{}1", s);
    let second = format!("{}2", s);
    let picked = match n {
        1 => first.clone(),
        2 => second,
        _ => format!("{}{}", first, second),
    };
    return format!("{} {}", picked, first);
}

fn main() {
    print!("{}", fact(5));
    print!("\n");
    print!("{}", pick("a", 1));
    print!(" ");
    print!("{}", pick("b", 2));
    print!(" ");
    print!("{}", pick("c", 3));
    print!("\n");
}
